/* Every captured UW undergraduate catalog credential has a source-text record. Audit interpretation stays explicit. */
let uwCurriculaPromise=null;
async function getUWCurricula(){if(!uwCurriculaPromise)uwCurriculaPromise=fetch('uw-curricula.json').then(r=>{if(!r.ok)throw Error('The UW source snapshot could not be loaded.');return r.json()}).then(data=>{if(!Array.isArray(data.records))throw Error('The UW snapshot has an invalid format.');return data}).catch(error=>{uwCurriculaPromise=null;throw error});return uwCurriculaPromise}
function uwCatalogCoverage(){const c=ProgramCatalog.uwCoverage;if(!c)return '';return `<details class="uw-coverage"><summary>${c.majorFamilies} UW undergraduate major families · ${c.selectableCredentials} catalog credentials/options</summary><p>Checked ${esc(c.checked)} across ${c.departmentPagesRead} official catalog department pages. Credentials/options are not counted as separate standalone majors. Graduate degrees, minors and non-bachelor professional degrees are outside this undergraduate catalog.</p><div class="uw-campus-counts">${c.campuses.map(s=>`<span><strong>${esc(s.institution)}</strong>${s.majorFamilies} major families · ${s.credentials} credentials/options</span>`).join('')}</div><p>All bachelor headings in the reviewed catalog indexes are represented. Catalog-listed does not mean applications are open or admission is guaranteed. Confirm your applicable catalog year.</p><details><summary>Catalog entries explicitly marked not admitting</summary>${c.notAdmitting.map(p=>`<p><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)} ↗</a></p>`).join('')}</details><p><a class="journey-secondary" href="uw-catalog-coverage.json" target="_blank" rel="noopener">Source coverage and exceptions ↗</a></p></details>`}
function uwMajorDirectory(){if(!['__uw_all__','UW Seattle','UW Bothell','UW Tacoma'].includes(programDirectorySchool))programDirectorySchool='__uw_all__';return programDirectory(true)}
function requirementTextSections(record){const sections=[];if(record.programAdmission)sections.push(['Program admission',record.programAdmission]);if(record.programCompletion)sections.push(['Program completion requirements',record.programCompletion]);for(const [key,value]of Object.entries(record.sections||{})){if(!value||sections.some(([,text])=>text===value))continue;sections.push([key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase()),value])}return sections}
async function showUWRequirements(id,target){target.hidden=false;target.innerHTML='<p role="status">Opening the published UW catalog requirements…</p>';try{const data=await getUWCurricula();if(!target.isConnected)return;const record=data.records.find(r=>r.id===id);if(!record)throw Error('No matching credential source was found. Open the official program link.');const sections=requirementTextSections(record);target.innerHTML=`<span class="eyebrow">OFFICIAL CATALOG SNAPSHOT · ${esc(record.checked)}</span><h3>${esc(record.credential)}</h3><p>${esc(record.institution)} · ${esc(record.catalogYear)}</p><a class="journey-secondary" href="${esc(record.url)}" target="_blank" rel="noopener">Open this exact credential in the UW catalog ↗</a><p class="plan-trust-alert">Published requirements are present below. This is source text, not an institution-approved automatic degree audit. OR choices, distribution lists, residency and admission conditions retain their original scope.</p>${sections.map(([heading,text])=>`<details class="uw-requirement-section" ${/admission|completion/i.test(heading)?'open':''}><summary>${esc(heading)}</summary><div class="uw-source-text" tabindex="0" role="region" aria-label="${esc(heading)}">${esc(text)}</div></details>`).join('')}${!record.programCompletion&&!Object.keys(record.sections||{}).some(k=>/completion/i.test(k))?'<p class="plan-trust-alert">This credential refers elsewhere for completion requirements. Follow the catalog referral; no missing requirements are assumed waived.</p>':''}${record.courseMentions?.length?`<details><summary>Course references in the published text</summary><p>${record.courseMentions.map(esc).join(' · ')}</p><p>Mentions are not automatically required courses. The source may list alternatives, examples or exclusions.</p></details>`:''}${record.literalNumericFacts?.length?`<details><summary>Published credit and GPA phrases — preserve context</summary><p>These can describe different admission, course and graduation rules. They are not one universal GPA cutoff.</p>${[...new Set(record.literalNumericFacts)].map(t=>`<blockquote>${esc(t)}</blockquote>`).join('')}</details>`:''}<button class="btn" data-save-uw-source="${esc(id)}">Attach these source requirements to my goal</button>`;target.querySelector('[data-save-uw-source]').onclick=()=>attachUWSource(record)}catch(error){if(target.isConnected)target.innerHTML=`<p role="alert">${esc(error.message)}</p>`}}
function attachUWSource(record){const goal=(state.degreeGoals||[]).find(g=>g.programId===record.id);if(!goal)return toast('Choose this credential as a primary or backup first, then attach its source.');goal.catalogId=record.id;goal.catalogSource=record.url;goal.catalogYear=record.catalogYear;save();toast('Official source attached. Enter or review the scheduling requirements before using an automatic plan.')}
function goalCatalogLinks(){const goals=(state.degreeGoals||[]).filter(g=>g.programId?.includes('-credential-'));return goals.length?`<section class="degree-optimizer"><h2>Your exact UW degree requirements</h2><p>Keep the source for each primary, backup or concurrent goal visible while entering its schedule constraints.</p>${goals.map(g=>`<article class="degree-goal"><h3>${esc(g.name)}</h3><button class="btn" data-uw-requirements="${esc(g.programId)}">Read published admission and degree requirements</button><div class="uw-requirements-reader" hidden></div></article>`).join('')}</section>`:''}
function bindUWCatalog(){document.querySelectorAll('[data-uw-requirements]').forEach(button=>button.onclick=()=>{let target=button.parentElement.querySelector('.uw-requirements-reader');if(!target){target=document.createElement('section');target.className='uw-requirements-reader degree-optimizer';button.parentElement.append(target)}showUWRequirements(button.dataset.uwRequirements,target)})}
function installUWCatalog(){const beforeExplore=explore;explore=()=>`<div class="degree-summary uw-explore-entry"><div><span class="eyebrow">SEATTLE · BOTHELL · TACOMA</span><strong>Explore every catalog-listed UW undergraduate major.</strong><p>Compare major families, exact degrees and formal options, with their published requirements.</p></div><a class="btn primary" href="#uw-majors">Browse UW majors →</a></div>`+beforeExplore();const beforeDegrees=degreePlanner;degreePlanner=()=>beforeDegrees()+goalCatalogLinks();const beforeBind=bind;bind=()=>{beforeBind();bindUWCatalog()}}
